def transform(grid):
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    background = counts.most_common(1)[0][0]
    other = next(x for x in counts if x != background)
    if background == 5:
        mapping = {background: other, other: 0}
    else:
        mapping = {background: 0, other: background}
    return [[mapping[x] for x in row] for row in grid]
